# A small vector-based drawing surface built with Tk Canvas.
import tkinter as tk


def paint_color(app, color):
    app.paint_color = color
    app.StatusLabel.configure(text="Drawing color: " + color)


def paint_start(app, event):
    # Freeze tool/color/width for the duration of one mouse stroke.
    app.paint_tool = app.ToolChoice.get()
    app.paint_width = max(1, min(30, int(app.StrokeScale.get())))
    app.paint_active_color = "white" if app.paint_tool == "Eraser" else app.paint_color
    app.paint_start = (event.x, event.y)
    app.paint_last = (event.x, event.y)
    app.paint_shape = None
    canvas = app.PaintCanvas
    if app.paint_tool in ("Brush", "Eraser"):
        radius = app.paint_width / 2
        canvas.create_oval(event.x-radius, event.y-radius, event.x+radius, event.y+radius, fill=app.paint_active_color, outline=app.paint_active_color)
    elif app.paint_tool == "Line":
        app.paint_shape = canvas.create_line(event.x, event.y, event.x, event.y, fill=app.paint_active_color, width=app.paint_width)
    elif app.paint_tool in ("Rectangle", "Oval"):
        creator = canvas.create_rectangle if app.paint_tool == "Rectangle" else canvas.create_oval
        app.paint_shape = creator(event.x, event.y, event.x, event.y, outline=app.paint_active_color, width=app.paint_width)


def paint_drag(app, event):
    # The eraser draws white strokes; it does not delete vector objects.
    if app.paint_last is None:
        return
    canvas = app.PaintCanvas
    if app.paint_tool in ("Brush", "Eraser"):
        canvas.create_line(*app.paint_last, event.x, event.y, fill=app.paint_active_color, width=app.paint_width, capstyle="round")
    elif app.paint_shape is not None:
        canvas.coords(app.paint_shape, *app.paint_start, event.x, event.y)
    app.paint_last = (event.x, event.y)


def paint_end(app, event):
    # Update the last endpoint even when the pointer moved quickly.
    paint_drag(app, event)
    app.paint_last = None
    app.paint_shape = None


def paint_clear(app):
    if not messagebox.askyesno("Clear drawing", "Clear the entire drawing?", parent=app.Form1):
        return
    app.PaintCanvas.delete("all")
    app.paint_last = None
    app.paint_shape = None


def paint_export(app):
    # Canvas exports EPS without Pillow; PNG/JPEG conversion is not included.
    filename = filedialog.asksaveasfilename(parent=app.Form1, defaultextension=".eps", filetypes=[("EPS drawing", "*.eps")])
    if not filename:
        return
    try:
        app.PaintCanvas.postscript(file=filename, colormode="color")
    except (OSError, tk.TclError) as error:
        messagebox.showerror("Export drawing", str(error), parent=app.Form1)
